INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Gilt das TKG nur für klassische Telefonie?', 2, '[{"text": "Nein", "correct": true, "because": "Auch OTT-Dienste wie Messenger enthalten"}, {"text": "Ja", "correct": false, "because": "Umfasst moderne Kommunikation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt das TKG im Datenschutz?', 3, '[{"text": "Fernmeldegeheimnis schützen", "correct": true, "because": "Sichert Kommunikation"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Kosten senken", "correct": false, "because": "Sicherheit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten haben Anbieter laut TKG?', 5, '[{"text": "Meldepflicht beim BSI", "correct": true, "because": "Registrierung erforderlich"}, {"text": "Datenschutz einhalten", "correct": true, "because": "Fernmeldegeheimnis schützen"}, {"text": "Maximale Speicherung", "correct": false, "because": "Widerspricht Datenschutz"}, {"text": "UI-Design", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) TKG regelt Datenschutz für Anbieter. b) Es ersetzt die DSGVO.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DSGVO bleibt maßgeblich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der TKG-Umsetzung?', 4, '[{"text": "Verkehrsdatenregelung", "correct": false, "because": "Kern des Datenschutzes"}, {"text": "Meldepflicht", "correct": false, "because": "Pflicht für Anbieter"}, {"text": "Grafisches Design", "correct": true, "because": "Kein Datenschutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das TKG auch Messenger-Dienste abdeckt?', 2, '[{"text": "Ja", "correct": true, "because": "Nummernunabhängige Dienste enthalten"}, {"text": "Nein", "correct": false, "because": "Moderne Kommunikation inklusive"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten schützt das TKG?', 3, '[{"text": "Kommunikationsinhalte", "correct": true, "because": "Fernmeldegeheimnis"}, {"text": "Serverleistung", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Bandbreite", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen fordert das TKG von Anbietern?', 5, '[{"text": "Verkehrsdaten begrenzen", "correct": true, "because": "Nur für Zweck erlaubt"}, {"text": "Datenschutz melden", "correct": true, "because": "Pannen ans BSI"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Widerspricht Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) TKG schützt Kommunikation. b) Es gilt nur für Festnetz. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Mobilfunk und OTT"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die TKG-Umsetzung?', 4, '[{"text": "Datenschutzrichtlinien", "correct": false, "because": "Pflicht für Anbieter"}, {"text": "Meldepflicht", "correct": false, "because": "Gesetzlich vorgeschrieben"}, {"text": "Maximale Datensammlung", "correct": true, "because": "Widerspricht Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Regelt das TKG auch Verbraucherschutz?', 2, '[{"text": "Ja", "correct": true, "because": "Vertragslaufzeiten und mehr"}, {"text": "Nein", "correct": false, "because": "Verbraucherrechte enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche deckt das TKG ab?', 4, '[{"text": "Kommunikationsdienste", "correct": true, "because": "Inklusive OTT"}, {"text": "Datenschutz", "correct": true, "because": "Fernmeldegeheimnis"}, {"text": "Servergeschwindigkeit", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das TKG nur für Anbieter gilt. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Fokus auf Diensteanbieter"}, {"text": "Nein", "correct": false, "because": "Anbieter sind Hauptziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich im TKG für Datenschutz?', 3, '[{"text": "Fernmeldegeheimnis", "correct": true, "because": "Schutz der Kommunikation"}, {"text": "Datenmenge erhöhen", "correct": false, "because": "Widerspricht Schutz"}, {"text": "Visuelle Gestaltung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) TKG fordert Meldepflicht. b) Es ignoriert Datenschutz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Datenschutz ist zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten schützt das TKG besonders?', 5, '[{"text": "Verkehrsdaten", "correct": true, "because": "Nur für Zweck erlaubt"}, {"text": "Kommunikationsinhalte", "correct": true, "because": "Fernmeldegeheimnis"}, {"text": "Unsortierte Daten", "correct": false, "because": "Nicht spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim TKG-Datenschutz unwichtig?', 3, '[{"text": "Vertraulichkeit", "correct": false, "because": "Kern des Schutzes"}, {"text": "Meldepflicht", "correct": false, "because": "Pflicht für Anbieter"}, {"text": "Animationen", "correct": true, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Gilt das TKG auch außerhalb Deutschlands?', 3, '[{"text": "Nein", "correct": true, "because": "Nationales Gesetz"}, {"text": "Ja", "correct": false, "because": "Nur deutscher Anwendungsbereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das TKG Bußgelder vorsieht?', 2, '[{"text": "Ja", "correct": true, "because": "Bei Verstößen möglich"}, {"text": "Nein", "correct": false, "because": "Sanktionen enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip wähle ich für TKG-Datenschutz?', 4, '[{"text": "Fernmeldegeheimnis", "correct": true, "because": "Schützt Kommunikation"}, {"text": "Maximale Datensammlung", "correct": false, "because": "Widerspricht Schutz"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Irrelevant"}]');
